}", "newString": "/**
 * Resolves an untrusted plan file reference to an absolute path within the
 * plans directory.
 *
 * The reference is treated flexibly to support nested directories and to stay
 * portable across machines:
 * - Absolute paths are used verbatim (and later validated for containment).
 * - Paths that, when resolved against the project root, land inside the plans
 *   directory are honored as-is. This matches how the plans directory is
 *   presented to the model in the system prompt (relative to the project root).
 * - Everything else is treated as relative to the plans directory itself,
 *   preserving any intermediate directories (e.g. `feature/plan.md`).
 *
 * @param planPath The untrusted path/filename of the plan file.
 * @param plansDir The authorized project plans directory (absolute path).
 * @param projectRoot The absolute path to the project root directory.
 * @returns The resolved absolute path to the plan file.
 */
export function resolvePlanFilePath(
  planPath: string,
  plansDir: string,
  projectRoot: string,
): string {
  if (path.isAbsolute(planPath)) {
    return planPath;
  }

  if (projectRoot) {
    const fromProjectRoot = path.resolve(projectRoot, planPath);
    // Use a lexical containment check here so that a symlink inside the plans
    // directory is still resolved to its location (and rejected later by the
    // real-path containment check in validatePlanPath).
    if (isSubpath(path.resolve(plansDir), fromProjectRoot)) {
      return fromProjectRoot;
    }
  }

  return path.join(plansDir, planPath);
}

/**
 * Validates a plan file path for safety (traversal) and existence.
 * @param planPath The untrusted path to the plan file.
 * @param plansDir The authorized project plans directory.
 * @param projectRoot The absolute path to the project root directory.
 * @returns An error message if validation fails, or null if successful.
 */
export async function validatePlanPath(
  planPath: string,
  plansDir: string,
  projectRoot: string,
): Promise<string | null> {
  const resolvedPath = resolvePlanFilePath(planPath, plansDir, projectRoot);
  const realPath = resolveToRealPath(resolvedPath);
  const realPlansDir = resolveToRealPath(plansDir);

  if (!isSubpath(realPlansDir, realPath)) {
    return PlanErrorMessages.PATH_ACCESS_DENIED(planPath, plansDir);
  }

  if (!(await fileExists(resolvedPath))) {
    return PlanErrorMessages.FILE_NOT_FOUND(planPath);
  }

  return null;
