25	/**
26	 * Resolves an untrusted plan file reference to an absolute path within the
27	 * plans directory.
28	 *
29	 * The reference is treated flexibly to support nested directories and to stay
30	 * portable across machines:
31	 * - Absolute paths are used verbatim (and later validated for containment).
32	 * - Paths that, when resolved against the project root, land inside the plans
33	 *   directory are honored as-is. This matches how the plans directory is
34	 *   presented to the model in the system prompt (relative to the project root).
35	 * - Everything else is treated as relative to the plans directory itself,
36	 *   preserving any intermediate directories (e.g. `feature/plan.md`).
37	 *
38	 * @param planPath The untrusted path/filename of the plan file.
39	 * @param plansDir The authorized project plans directory (absolute path).
40	 * @param projectRoot The absolute path to the project root directory.
41	 * @returns The resolved absolute path to the plan file.
42	 */
43	export function resolvePlanFilePath(
44	  planPath: string,
45	  plansDir: string,
46	  projectRoot: string,
47	): string {
48	  if (path.isAbsolute(planPath)) {
49	    return planPath;
50	  }
51	
52	  if (projectRoot) {
53	    const fromProjectRoot = path.resolve(projectRoot, planPath);
54	    // Use a lexical containment check here so that a symlink inside the plans
55	    // directory is still resolved to its location (and rejected later by the
56	    // real-path containment check in validatePlanPath).
57	    if (isSubpath(path.resolve(plansDir), fromProjectRoot)) {
58	      return fromProjectRoot;
59	    }
60	  }
61	
62	  return path.join(plansDir, planPath);
63	}
