65	/**
66	 * Validates a plan file path for safety (traversal) and existence.
67	 * @param planPath The untrusted path to the plan file.
68	 * @param plansDir The authorized project plans directory.
69	 * @param projectRoot The absolute path to the project root directory.
70	 * @returns An error message if validation fails, or null if successful.
71	 */
72	export async function validatePlanPath(
73	  planPath: string,
74	  plansDir: string,
75	  projectRoot: string,
76	): Promise<string | null> {
77	  const resolvedPath = resolvePlanFilePath(planPath, plansDir, projectRoot);
78	  const realPath = resolveToRealPath(resolvedPath);
79	  const realPlansDir = resolveToRealPath(plansDir);
80	
81	  if (!isSubpath(realPlansDir, realPath)) {
82	    return PlanErrorMessages.PATH_ACCESS_DENIED(planPath, plansDir);
83	  }
84	
85	  if (!(await fileExists(resolvedPath))) {
86	    return PlanErrorMessages.FILE_NOT_FOUND(planPath);
87	  }
88	
89	  return null;
90	}
